CREATE TABLE invoice (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project_id BIGINT         NOT NULL,
    amount     DECIMAL(12, 2) NOT NULL,
    CONSTRAINT invoice_project_fk FOREIGN KEY (project_id) REFERENCES project (id),
    CONSTRAINT invoice_amount_positive CHECK (amount > 0)
);

CREATE INDEX invoice_project_idx ON invoice (project_id);
ALTER TABLE invoice ADD COLUMN status VARCHAR(16) DEFAULT 'UNPAID' NOT NULL;

ALTER TABLE invoice ADD CONSTRAINT invoice_status_valid CHECK (status IN ('UNPAID', 'PAID'));
-- Every invoice carries the date it was issued (sent out) and the date payment is due.
-- Backfill any existing rows: issued today, due 30 days later.
ALTER TABLE invoice ADD COLUMN issued_date DATE DEFAULT CURRENT_DATE NOT NULL;
ALTER TABLE invoice ADD COLUMN due_date DATE;
UPDATE invoice SET due_date = DATEADD('DAY', 30, issued_date) WHERE due_date IS NULL;
ALTER TABLE invoice ALTER COLUMN due_date SET NOT NULL;

ALTER TABLE invoice ADD CONSTRAINT invoice_due_after_issued CHECK (due_date >= issued_date);
package net.officefloor.hq.app.invoice;

import jakarta.validation.Valid;
import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/projects/{projectId}/invoices")
public class InvoiceController {

    private final InvoiceService service;

    public InvoiceController(InvoiceService service) {
        this.service = service;
    }

    @GetMapping
    public List<InvoiceResponse> list(@PathVariable Long projectId) {
        return service.listForProject(projectId);
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public InvoiceResponse create(@PathVariable Long projectId, @Valid @RequestBody InvoiceRequest request) {
        return service.create(projectId, request);
    }

    @PostMapping("/{invoiceId}/pay")
    public InvoiceResponse pay(@PathVariable Long projectId, @PathVariable Long invoiceId) {
        return service.pay(projectId, invoiceId);
    }
}
package net.officefloor.hq.app.invoice;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.project.Project;

/** An invoice raised against a project. */
@Entity
@Table(name = "invoice")
public class Invoice {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "project_id", nullable = false)
    private Project project;

    @Column(nullable = false, precision = 12, scale = 2)
    private BigDecimal amount;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 16)
    private InvoiceStatus status = InvoiceStatus.UNPAID;

    @Column(name = "issued_date", nullable = false)
    private LocalDate issuedDate;

    @Column(name = "due_date", nullable = false)
    private LocalDate dueDate;

    protected Invoice() {
    }

    public Invoice(Project project, BigDecimal amount, LocalDate issuedDate, LocalDate dueDate) {
        this.project = project;
        this.amount = amount;
        this.issuedDate = issuedDate;
        this.dueDate = dueDate;
    }

    public Long getId() {
        return id;
    }

    public Project getProject() {
        return project;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public InvoiceStatus getStatus() {
        return status;
    }

    public LocalDate getIssuedDate() {
        return issuedDate;
    }

    public LocalDate getDueDate() {
        return dueDate;
    }

    /** Marks this invoice as paid. */
    public void markPaid() {
        this.status = InvoiceStatus.PAID;
    }
}
