package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Truncate the audit file (called by /__test__/reset for per-spec isolation). */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.invoice.InvoiceRequest;
import net.officefloor.hq.app.invoice.InvoiceStatus;
import org.springframework.context.annotation.Profile;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * Per-spec data setup for the end-to-end tests. Profile-guarded so it exists ONLY under the test
 * launch (bin/start sets spring.profiles.active=e2e) — never in a real deploy. Tests call these to
 * ARRANGE data; they ASSERT only through the UI.
 */
@Profile("e2e")
@RestController
@RequestMapping("/__test__")
public class TestSupportController {

    private final Audit audit;
    private final JdbcTemplate jdbc;

    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
        this.audit = audit;
        this.jdbc = jdbc;
    }

    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
    @PostMapping("/reset")
    @Transactional
    public void reset() {
        audit.clear();
        // Children first; H2 refuses to TRUNCATE a table referenced by a foreign key, so disable
        // referential checks for the duration of the truncates.
        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
        try {
            jdbc.execute("TRUNCATE TABLE invoice RESTART IDENTITY");
            jdbc.execute("TRUNCATE TABLE project RESTART IDENTITY");
            jdbc.execute("TRUNCATE TABLE client RESTART IDENTITY");
        } finally {
            jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
        }
    }

    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
    @PostMapping("/seed")
    @Transactional
    public void seed(@RequestBody Map<String, Object> fixture) {
        for (Map<String, Object> c : rows(fixture, "clients")) {
            jdbc.update("INSERT INTO client (id, name, email) VALUES (?, ?, ?)",
                    ((Number) c.get("id")).longValue(), c.get("name"), c.get("email"));
        }
        for (Map<String, Object> p : rows(fixture, "projects")) {
            jdbc.update("INSERT INTO project (id, name, client_id) VALUES (?, ?, ?)",
                    ((Number) p.get("id")).longValue(), p.get("name"),
                    ((Number) p.get("clientId")).longValue());
        }
        for (Map<String, Object> i : rows(fixture, "invoices")) {
            LocalDate issued = i.get("issuedDate") == null ? LocalDate.now()
                    : LocalDate.parse(i.get("issuedDate").toString());
            LocalDate due = i.get("dueDate") == null ? issued.plusDays(InvoiceRequest.DEFAULT_TERM_DAYS)
                    : LocalDate.parse(i.get("dueDate").toString());
            jdbc.update("INSERT INTO invoice (id, project_id, amount, status, issued_date, due_date)"
                    + " VALUES (?, ?, ?, ?, ?, ?)",
                    ((Number) i.get("id")).longValue(), ((Number) i.get("projectId")).longValue(),
                    new BigDecimal(i.get("amount").toString()),
                    seedStatus(i.get("status")), issued, due);
        }
        // Continue generated ids after the explicitly seeded ones.
        restartIdentity("client");
        restartIdentity("project");
        restartIdentity("invoice");
    }

    /**
     * Fixtures may describe an issued-but-unpaid invoice as "SENT"; this domain models that state
     * as UNPAID.
     */
    private static String seedStatus(Object status) {
        if (status == null || "SENT".equals(status)) {
            return InvoiceStatus.UNPAID.name();
        }
        return status.toString();
    }

    private void restartIdentity(String table) {
        Long next = jdbc.queryForObject("SELECT COALESCE(MAX(id), 0) + 1 FROM " + table, Long.class);
        jdbc.execute("ALTER TABLE " + table + " ALTER COLUMN id RESTART WITH " + next);
    }

    @SuppressWarnings("unchecked")
    private static List<Map<String, Object>> rows(Map<String, Object> fixture, String key) {
        Object value = fixture.get(key);
        return value == null ? List.of() : (List<Map<String, Object>>) value;
    }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

export type InvoiceStatus = 'UNPAID' | 'PAID';

export interface Invoice {
  id: number;
  projectId: number;
  amount: number;
  status: InvoiceStatus;
  /** ISO date (yyyy-MM-dd) the invoice was issued. */
  issuedDate: string;
  /** ISO date (yyyy-MM-dd) payment is due. */
  dueDate: string;
}

export interface NewInvoice {
  amount: number;
  /** Defaults to today on the server when omitted. */
  issuedDate?: string;
  /** Defaults to 30 days after the issue date on the server when omitted. */
  dueDate?: string;
}

@Injectable({ providedIn: 'root' })
export class InvoiceService {
  private readonly http = inject(HttpClient);

  listForProject(projectId: number): Observable<Invoice[]> {
    return this.http.get<Invoice[]>(`/api/projects/${projectId}/invoices`);
  }

  create(projectId: number, invoice: NewInvoice): Observable<Invoice> {
    return this.http.post<Invoice>(`/api/projects/${projectId}/invoices`, invoice);
  }

  pay(projectId: number, invoiceId: number): Observable<Invoice> {
    return this.http.post<Invoice>(`/api/projects/${projectId}/invoices/${invoiceId}/pay`, null);
  }
}
import { CurrencyPipe } from '@angular/common';
import { Component, computed, inject, input, signal } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
import {
  AbstractControl,
  NonNullableFormBuilder,
  ReactiveFormsModule,
  ValidationErrors,
  Validators,
} from '@angular/forms';
import { InvoiceService } from './invoice.service';

// ISO yyyy-MM-dd strings compare correctly as plain strings.
function dueNotBeforeIssued(group: AbstractControl): ValidationErrors | null {
  const { issuedDate, dueDate } = group.value as { issuedDate?: string; dueDate?: string };
  return issuedDate && dueDate && dueDate < issuedDate ? { dueBeforeIssued: true } : null;
}

// A project's invoices: lists them with their issue and due dates, shows what they add up to, adds a
// new one, and marks one as paid.
@Component({
  selector: 'app-project-invoices',
  imports: [ReactiveFormsModule, CurrencyPipe],
  template: `
    <section aria-labelledby="project-invoices-heading" data-testid="project-invoices">
      <h2 id="project-invoices-heading">Invoices</h2>

      <form [formGroup]="form" (ngSubmit)="submit()" data-testid="invoice-form" novalidate>
        <div>
          <label for="invoice-amount">Amount</label>
          <input
            id="invoice-amount"
            type="number"
            inputmode="decimal"
            min="0.01"
            step="0.01"
            formControlName="amount"
            data-testid="invoice-form-amount"
            [attr.aria-invalid]="showError()"
            [attr.aria-describedby]="showError() ? 'invoice-amount-error' : null"
          />
          @if (showError()) {
            <p id="invoice-amount-error" role="alert" data-testid="invoice-form-amount-error">
              Enter an amount greater than zero with at most two decimal places.
            </p>
          }
        </div>
        <div>
          <label for="invoice-issued">Issued (optional, defaults to today)</label>
          <input id="invoice-issued" type="date" formControlName="issuedDate" data-testid="invoice-form-issued" />
        </div>
        <div>
          <label for="invoice-due">Due (optional, defaults to 30 days after issue)</label>
          <input
            id="invoice-due"
            type="date"
            formControlName="dueDate"
            data-testid="invoice-form-due"
            [attr.aria-invalid]="showDueError()"
            [attr.aria-describedby]="showDueError() ? 'invoice-due-error' : null"
          />
          @if (showDueError()) {
            <p id="invoice-due-error" role="alert" data-testid="invoice-form-due-error">
              The due date cannot be before the issue date.
            </p>
          }
        </div>
        <button type="submit" data-testid="invoice-form-submit" [disabled]="saving()">
          Add invoice
        </button>
        @if (saveError()) {
          <p role="alert" data-testid="invoice-form-error">{{ saveError() }}</p>
        }
      </form>

      @if (invoices.error()) {
        <p role="alert" data-testid="project-invoices-error">Could not load the invoices.</p>
      } @else if (list().length === 0) {
        <p data-testid="project-invoices-empty">No invoices yet.</p>
      } @else {
        <table data-testid="project-invoices-table">
          <caption>Invoices for this project</caption>
          <thead>
            <tr>
              <th scope="col">Invoice</th>
              <th scope="col">Amount</th>
              <th scope="col">Status</th>
              <th scope="col">Issued</th>
              <th scope="col" [attr.aria-sort]="sortByDue() ? 'ascending' : null">
                <button
                  type="button"
                  data-testid="invoice-sort-due"
                  [attr.aria-pressed]="sortByDue()"
                  (click)="sortByDue.set(!sortByDue())"
                >
                  Due<span class="visually-hidden">, sort earliest first</span>
                </button>
              </th>
              <th scope="col"><span class="visually-hidden">Actions</span></th>
            </tr>
          </thead>
          <tbody>
            @for (i of rows(); track i.id) {
              <tr [attr.data-testid]="'invoice-row-' + i.id">
                <td data-testid="invoice-id">#{{ i.id }}</td>
                <td data-testid="invoice-amount">{{ i.amount | currency: 'USD' : 'symbol' : '1.2-2' : 'en-US' }}</td>
                <td data-testid="invoice-status">{{ i.status }}</td>
                <td data-testid="invoice-issued">{{ i.issuedDate }}</td>
                <td data-testid="invoice-due">{{ i.dueDate }}</td>
                <td>
                  @if (i.status === 'UNPAID') {
                    <button
                      type="button"
                      [attr.data-testid]="'invoice-pay-' + i.id"
                      [attr.aria-label]="'Mark invoice #' + i.id + ' as paid'"
                      [disabled]="paying() === i.id"
                      (click)="pay(i.id)"
                    >
                      Mark paid
                    </button>
                  }
                </td>
              </tr>
            }
          </tbody>
          <tfoot>
            <tr>
              <th scope="row">Total</th>
              <td data-testid="project-invoices-total">{{ totalCents() / 100 | currency: 'USD' : 'symbol' : '1.2-2' : 'en-US' }}</td>
              <td colspan="4"></td>
            </tr>
          </tfoot>
        </table>
        @if (payError()) {
          <p role="alert" data-testid="invoice-pay-error">{{ payError() }}</p>
        }
      }
    </section>
  `,
})
export class ProjectInvoices {
  private readonly service = inject(InvoiceService);

  readonly projectId = input.required<number>();

  protected readonly invoices = rxResource({
    params: () => this.projectId(),
    stream: ({ params }) => this.service.listForProject(params),
  });
  protected readonly list = computed(() => (this.invoices.hasValue() ? this.invoices.value() : []));
  // Earliest due first when sorting by due date (ties by invoice number); otherwise invoice-number order.
  protected readonly sortByDue = signal(false);
  protected readonly rows = computed(() =>
    this.sortByDue()
      ? [...this.list()].sort((a, b) => a.dueDate.localeCompare(b.dueDate) || a.id - b.id)
      : this.list(),
  );
  // Sum in whole cents so the total is exact rather than accumulating floating-point error.
  protected readonly totalCents = computed(() =>
    this.list().reduce((sum, i) => sum + Math.round(i.amount * 100), 0),
  );

  protected readonly saving = signal(false);
  protected readonly saveError = signal<string | null>(null);

  protected readonly paying = signal<number | null>(null);
  protected readonly payError = signal<string | null>(null);

  protected readonly form = inject(NonNullableFormBuilder).group(
    {
      amount: [
        '',
        [Validators.required, Validators.min(0.01), Validators.pattern(/^\d+(\.\d{1,2})?$/)],
      ],
      issuedDate: [''],
      dueDate: [''],
    },
    { validators: dueNotBeforeIssued },
  );

  protected showDueError(): boolean {
    return this.form.hasError('dueBeforeIssued') && this.form.controls.dueDate.dirty;
  }

  protected showError(): boolean {
    const control = this.form.controls.amount;
    return control.invalid && (control.touched || control.dirty);
  }

  protected submit(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }
    this.saving.set(true);
    this.saveError.set(null);
    const { amount, issuedDate, dueDate } = this.form.getRawValue();
    const invoice = {
      amount: Number(amount),
      ...(issuedDate ? { issuedDate } : {}),
      ...(dueDate ? { dueDate } : {}),
    };
    this.service.create(this.projectId(), invoice).subscribe({
      next: (created) => {
        this.invoices.update((list) => [...(list ?? []), created]);
        this.form.reset();
        this.saving.set(false);
      },
      error: () => {
        this.saveError.set('Could not save the invoice. Please try again.');
        this.saving.set(false);
      },
    });
  }

  protected pay(invoiceId: number): void {
    this.paying.set(invoiceId);
    this.payError.set(null);
    this.service.pay(this.projectId(), invoiceId).subscribe({
      next: (paid) => {
        this.invoices.update((list) => (list ?? []).map((i) => (i.id === paid.id ? paid : i)));
        this.paying.set(null);
      },
      error: () => {
        this.payError.set('Could not mark the invoice as paid. Please try again.');
        this.paying.set(null);
      },
    });
  }
}
import { existsSync, readFileSync } from 'node:fs';

// Read the known audit file — the second test-assertion channel alongside the UI. The app appends
// one record per line; /__test__/reset clears it per spec. Path comes from AUDIT_FILE (set by
// bin/start / bin/e2e); falls back to the app's default.
const AUDIT_FILE = process.env.AUDIT_FILE ?? '../.run/audit.log';

/** All audit records currently in the file, one per element (empty if none). */
export function auditLines(): string[] {
  return existsSync(AUDIT_FILE)
    ? readFileSync(AUDIT_FILE, 'utf8').split('\n').filter((l) => l.length > 0)
    : [];
}

// Usage in a spec (audit-category test):
//   expect(auditLines()).toContain('OWNER_CREATED id=1 name=Acme');
// Shared per-spec data setup. Each spec's beforeEach RESETS then SEEDS via the app's /__test__
// endpoint — this is Arrange, not Assert. Specs still ASSERT only through the UI (data-testid).
//
// FAIL LOUD: /__test__/reset and /__test__/seed are the Arrange for EVERY spec, so they are a hard
// precondition — if either does not return 2xx the data is not in the state the test assumes, and a
// silent failure would surface later as confusing, misattributed assertion failures on unrelated
// specs (e.g. leftover rows because reset could not clear an FK-referenced table). We throw here so
// the break is attributed to the seed contract, and so a developer running its own spec sees the
// broken endpoint immediately instead of shipping it.
import { request, type APIResponse } from '@playwright/test';

const BASE = process.env.BASE_URL ?? `http://localhost:${process.env.PORT ?? 3000}`;

async function must(res: Promise<APIResponse>, what: string): Promise<void> {
  const r = await res;
  if (!r.ok()) {
    const body = (await r.text().catch(() => '')).slice(0, 500);
    throw new Error(`seed contract broken: ${what} returned HTTP ${r.status()} — ${body}`);
  }
}

export async function resetAndSeed(fixture: unknown): Promise<void> {
  const api = await request.newContext({ baseURL: BASE });
  try {
    await must(api.post('/__test__/reset'), 'POST /__test__/reset');
    await must(api.post('/__test__/seed', { data: fixture }), 'POST /__test__/seed');
  } finally {
    await api.dispose();
  }
}

